 "edits": [
   {"old": "    tool_use_id: task.toolUseId,\n    description: task.description,",
    "new": "    tool_use_id: task.toolUseId as string | undefined,\n    description: task.description as string,"}
 ],
 "patterns": [
   {"patron": "task-state-index-signature-unknown",
    "senal_del_verificador": "framework\\.ts.*: TS2322: Type 'unknown' is not assignable to type '(string|string \\| undefined)'",
